# --- Bloques del reporte: (título, gráficos, tablas) -------------------------
def bloques_reporte() -> list[tuple[str, list[str], list[str]]]:
    """Secciones del reporte como (título, claves de gráficos, claves de tablas)."""
    tops = [k for k in TABLES if k.startswith("top_")]  # puede haber tabla sin gráfico
    return [
        ("Embudo del pipeline", ["embudo"], ["embudo"]),
        ("Motivos de eliminación", ["motivos"], ["motivos"]),
        ("Borrados a mano: franquicias", ["borrados_mano"], ["borrados_mano"]),
        ("Qué disparó las eliminaciones", tops, tops),
        ("Impacto por categoría", ["categorias"], ["categorias", "arrasadas"]),
        ("Duplicados agrupados", [], ["grupos", "grupos_mayores"]),
        ("Cobertura geográfica", [], ["geografia"]),
    ]

def exportar_html() -> Path:
    """Escribe el reporte como HTML autocontenido y devuelve la ruta."""
    REPORTS.mkdir(parents=True, exist_ok=True)
    out = nombre_reporte(".html")

    def tabla(key: str) -> str:
        # Misma tabla formateada que se ve en el notebook: el formato no se duplica
        return TABLES[key].to_html(index=False, border=0) if key in TABLES else ""

    cuerpo = ""
    for titulo, figs, tablas in bloques_reporte():
        # Cada gráfico va seguido de su tabla equivalente (lectura sin depender del color)
        if figs and figs == tablas:
            piezas = "".join(
                (f'<img src="data:image/png;base64,{FIGS[k]}" alt="{html.escape(k)}">' if k in FIGS else "")
                + tabla(k)
                for k in tablas
            )
        else:
            piezas = "".join(
                f'<img src="data:image/png;base64,{FIGS[k]}" alt="{html.escape(titulo)}">'
                for k in figs if k in FIGS
            ) + "".join(tabla(k) for k in tablas)
        if piezas:
            cuerpo += f"<section><h2>{html.escape(titulo)}</h2>{piezas}</section>"

    tarjetas = "".join(
        f'<div class="card{" destacada" if d else ""}">'
        f'<span class="k"><i>{op}</i>{html.escape(t)}</span>'
        f'<span class="v">{html.escape(v)}</span><span class="s">{html.escape(s)}</span></div>'
        for op, t, v, s, d in TARJETAS
    )

    # Los avisos viajan con el reporte: quien lo lea tiene que ver las salvedades
    alertas = "".join(
        f'<div class="alert">⚠️ {html.escape(a)}</div>' for a in AVISOS
    )

    out.write_text(f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<title>Reporte ejecutivo — limpieza Dataplor {html.escape(COUNTRY)}</title>
<style>
  body {{ font-family:system-ui,'Segoe UI',sans-serif; background:#f9f9f7; color:{C['ink']};
         margin:0; padding:32px; }}
  main {{ max-width:1040px; margin:auto; background:{C['surface']};
          border:1px solid rgba(11,11,11,.10); border-radius:14px; padding:32px 36px; }}
  h1 {{ font-size:24px; margin:0 0 4px; }}
  h2 {{ font-size:16px; margin:34px 0 12px; padding-bottom:8px;
        border-bottom:1px solid {C['grid']}; color:{C['ink']}; }}
  .meta {{ color:{C['muted']}; font-size:13px; margin-bottom:24px; }}
  .hero {{ font-size:52px; color:{C['kept']}; line-height:1; }}
  .hero small {{ display:block; font-size:14px; color:{C['ink2']}; margin-top:6px; }}
  .cards {{ display:flex; gap:12px; flex-wrap:wrap; margin:20px 0 8px; }}
  .card {{ flex:1 1 165px; border:1px solid rgba(11,11,11,.10); border-radius:10px; padding:14px 16px; }}
  .card .k {{ display:block; font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:{C['muted']}; }}
  .card .k i {{ font-style:normal; color:{C['muted']}; margin-right:4px; }}
  .card .v {{ display:block; font-size:27px; margin:5px 0 2px; }}
  .card .s {{ display:block; font-size:12.5px; color:{C['ink2']}; }}
  /* El entregable final va resaltado: es el número que se busca de un vistazo */
  .card.destacada {{ border:2px solid {C['kept']}; background:#f1f6fd; }}
  .card.destacada .k {{ color:{C['kept']}; font-weight:700; }}
  .card.destacada .v {{ color:{C['kept']}; font-weight:700; font-size:31px; }}
  .card.destacada .s {{ font-weight:600; }}
  .alert {{ border:1px solid #ec835a; background:#fdf3ee; color:{C['ink']}; font-size:13px;
            border-radius:8px; padding:10px 14px; margin:14px 0 0; }}
  img {{ max-width:100%; display:block; margin:14px 0 18px; }}
  table {{ border-collapse:collapse; width:100%; font-size:13px; margin:10px 0 22px;
           font-variant-numeric:tabular-nums; }}
  th {{ text-align:left; color:{C['ink2']}; font-weight:600; border-bottom:1px solid {C['axis']}; }}
  td {{ border-bottom:1px solid {C['grid']}; color:{C['ink']}; }}
  th, td {{ padding:7px 10px; }}
  tr:hover td {{ background:#f4f4f1; }}
</style></head><body><main>
  <h1>Reporte ejecutivo — limpieza Dataplor</h1>
  <div class="meta">País {html.escape(COUNTRY)}{(" · embotellador " + html.escape(BOTTLER)) if BOTTLER else ""} · generado {time.strftime("%Y-%m-%d %H:%M")} ·
     entrada <code>{html.escape(RAW_FILE.name)}</code> · salida <code>{html.escape(FINAL_FILE.name)}</code></div>
  <div class="hero">{html.escape(pct(retencion))}<small>{html.escape(HERO_DETALLE)}</small></div>
  <div class="cards">{tarjetas}</div>
  {alertas}
  {cuerpo}
</main></body></html>""", encoding="utf-8")
    return out
